artifacts.solve_py:
#!/usr/bin/env python3
import os
import csv
import json
import math
from pyscipopt import Model, quicksum

DATA = "/app/data"
OUT = "/app/submissions"
os.makedirs(OUT, exist_ok=True)

# ---------------- Load data ----------------
with open(os.path.join(DATA, "config.json")) as f:
    cfg = json.load(f)
DAYS = list(range(1, cfg["planning_days"] + 1))
CO_VISIT = cfg.get("co_visit_setup_saving_hours", 0.5)

def read_csv(name):
    with open(os.path.join(DATA, name), newline="") as f:
        return list(csv.DictReader(f))

vessels = {}
for r in read_csv("vessels.csv"):
    vessels[r["vessel_id"]] = {
        "berths": int(r["technician_berths"]),
        "deck": int(r["deck_spare_units"]),
        "fatigue": float(r["two_day_fatigue_limit"]),
    }

turbines = {}
for r in read_csv("turbines.csv"):
    turbines[r["turbine_id"]] = r["string_id"]

patterns = []
for r in read_csv("route_patterns.csv"):
    patterns.append({
        "id": r["pattern_id"],
        "day": int(r["day"]),
        "vessel": r["vessel_id"],
        "turbines": [t for t in r["covered_turbines"].split(";") if t],
        "cap": float(r["work_hour_capacity"]),
        "cost": float(r["route_cost"]),
        "capability": r["capability"].strip(),
        "access": int(r["access_score"]),
        "fatigue": float(r["fatigue_units"]),
    })
pat_by_id = {p["id"]: p for p in patterns}

work_orders = []
for r in read_csv("work_orders.csv"):
    work_orders.append({
        "id": r["task_id"],
        "turbine": r["turbine_id"],
        "type": r["task_type"].strip(),
        "skill": r["skill"].strip(),
        "mandatory": r["mandatory"].strip().lower() == "yes",
        "earliest": int(r["earliest_day"]),
        "due": int(r["due_day"]),
        "latest": int(r["latest_day"]),
        "hours": float(r["duration_hours"]),
        "tech": int(r["technicians_required"]),
        "spare_type": r["spare_type"].strip(),
        "spare_units": int(r["spare_units"]),
        "capability": r["required_capability"].strip(),
        "min_access": int(r["min_access_score"]),
        "lateness": float(r["lateness_penalty_per_day"]),
        "downtime": float(r["downtime_cost_per_day"]),
        "deferral": float(r["deferral_penalty"]),
        "credit": float(r["opportunity_credit"]),
    })
wo_by_id = {w["id"]: w for w in work_orders}

tech_pool = {}
for r in read_csv("technician_pool.csv"):
    d = int(r["day"]); s = r["skill"].strip()
    tech_pool[(d, s)] = {
        "regular": float(r["regular_hours"]),
        "ot_hours": float(r["overtime_hours"]),
        "ot_cost": float(r["overtime_cost_per_hour"]),
    }

spare_inv = {}
for r in read_csv("spare_inventory.csv"):
    spare_inv[(int(r["day"]), r["spare_type"].strip())] = int(r["available_units"])

sail_limits = {}
for r in read_csv("vessel_sailing_limits.csv"):
    sail_limits[r["vessel_id"]] = int(r["max_sailing_days"])

turnaround = []
for r in read_csv("route_turnaround_rules.csv"):
    turnaround.append((r["previous_pattern_id"].strip(), r["next_pattern_id"].strip()))

string_limits = {}
for r in read_csv("string_daily_limits.csv"):
    string_limits[r["string_id"].strip()] = (int(r["max_mandatory_tasks_per_day"]), int(r["max_total_tasks_per_day"]))

string_rules = []
for r in read_csv("string_opportunity_rules.csv"):
    string_rules.append({
        "id": r["rule_id"].strip(),
        "anchor": r["anchor_task_id"].strip(),
        "string": r["string_id"].strip(),
        "types": [t.strip() for t in r["eligible_task_types"].split(";") if t.strip()],
        "credit": float(r["credit_per_task"]),
        "max": int(r["max_credit_tasks"]),
    })

# ---------------- Eligibility ----------------
def cap_rank(c):
    return 1 if c == "cable" else 0

eligible = {}  # (w_id, p_id) -> True
for w in work_orders:
    for p in patterns:
        if not (w["earliest"] <= p["day"] <= w["latest"]):
            continue
        if w["turbine"] not in p["turbines"]:
            continue
        if cap_rank(p["capability"]) < cap_rank(w["capability"]):
            continue
        if p["access"] < w["min_access"]:
            continue
        eligible[(w["id"], p["id"])] = True

# ---------------- Build model ----------------
model = Model("offshore_wind_maintenance")
model.setParam("gaprel", 0.0005)
time_limit = 300.0
env = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if env is not None:
    try:
        time_limit = min(time_limit, float(env))
    except ValueError:
        pass
model.setParam("limits/time", time_limit)

x = {}
for p in patterns:
    x[p["id"]] = model.addVar(name=f"x_{p['id']}", vtype="B", lb=0, ub=1, obj=0.0)

y = {}
for w in work_orders:
    for p in patterns:
        if (w["id"], p["id"]) in eligible:
            y[(w["id"], p["id"])] = model.addVar(name=f"y_{w['id']}_{p['id']}", vtype="B", lb=0, ub=1, obj=0.0)

z = {}
for w in work_orders:
    z[w["id"]] = model.addVar(name=f"z_{w['id']}", vtype="B", lb=0, ub=1, obj=0.0)

# completion day and lateness
dayv = {}
latv = {}
for w in work_orders:
    dayv[w["id"]] = model.addVar(name=f"day_{w['id']}", vtype="C", lb=w["earliest"], ub=w["latest"], obj=0.0)
    latv[w["id"]] = model.addVar(name=f"lat_{w['id']}", vtype="C", lb=0.0, ub=float(w["latest"] - w["due"]), obj=0.0)

# co-visit saving vars: per pattern, per turbine (max 2 work orders per turbine per day in this instance; general: saving <= n-1)
sv = {}
for p in patterns:
    for t in p["turbines"]:
        wos_at_t = [w for w in work_orders if w["turbine"] == t and (w["id"], p["id"]) in eligible]
        if len(wos_at_t) >= 2:
            sv[(p["id"], t)] = model.addVar(name=f"sv_{p['id']}_{t}", vtype="B", lb=0, ub=1, obj=0.0)

# overtime vars
ot = {}
for d in DAYS:
    for s in ["blade", "electrical", "mechanical", "cable"]:
        if (d, s) in tech_pool:
            ot[(d, s)] = model.addVar(name=f"ot_{d}_{s}", vtype="C", lb=0.0, ub=tech_pool[(d, s)]["ot_hours"], obj=0.0)

# same-turbine credit vars
cvar = {}
for w in work_orders:
    if w["mandatory"]:
        continue
    for p in patterns:
        if (w["id"], p["id"]) in eligible:
            mand_at_t = [w2 for w2 in work_orders if w2["mandatory"] and w2["turbine"] == w["turbine"] and (w2["id"], p["id"]) in eligible]
            if mand_at_t:
                cvar[(w["id"], p["id"])] = model.addVar(name=f"c_{w['id']}_{p['id']}", vtype="B", lb=0, ub=1, obj=0.0)

# string credit vars
uvar = {}
for rule in string_rules:
    for w in work_orders:
        if w["id"] == rule["anchor"]:
            continue
        if turbines.get(w["turbine"]) != rule["string"]:
            continue
        if w["type"] not in rule["types"]:
            continue
        for p in patterns:
            if (w["id"], p["id"]) in eligible:
                # anchor must be doable on same day
                anchor_ok = any((rule["anchor"], p2["id"]) in eligible and p2["day"] == p["day"] for p2 in patterns)
                if anchor_ok:
                    uvar[(rule["id"], w["id"], p["id"])] = model.addVar(name=f"u_{rule['id']}_{w['id']}_{p['id']}", vtype="B", lb=0, ub=1, obj=0.0)

# ---------------- Constraints ----------------
# 1. completion definition
for w in work_orders:
    model.addCons(z[w["id"]] == quicksum(y[(w["id"], p["id"])] for p in patterns if (w["id"], p["id"]) in eligible), name=f"zdef_{w['id']}")
    if w["mandatory"]:
        model.chgVarLb(z[w["id"]], 1.0)

# 2. y <= x
for (wid, pid), v in y.items():
    model.addCons(v <= x[pid], name=f"ylink_{wid}_{pid}")

# 3. one pattern per vessel per day
for d in DAYS:
    for v in vessels:
        plist = [p["id"] for p in patterns if p["day"] == d and p["vessel"] == v]
        if plist:
            model.addCons(quicksum(x[pid] for pid in plist) <= 1, name=f"onepat_{v}_{d}")

# 4. sailing limits
for v in vessels:
    plist = [p["id"] for p in patterns if p["vessel"] == v]
    if plist:
        model.addCons(quicksum(x[pid] for pid in plist) <= sail_limits.get(v, 99), name=f"sail_{v}")

# 5. turnaround bans
for prev, nxt in turnaround:
    if prev in x and nxt in x:
        model.addCons(x[prev] + x[nxt] <= 1, name=f"turn_{prev}_{nxt}")

# 6. two-day fatigue
for v in vessels:
    for d in DAYS:
        plist = [p["id"] for p in patterns if p["vessel"] == v and p["day"] in (d, d + 1)]
        if plist:
            model.addCons(quicksum(pat_by_id[pid]["fatigue"] * x[pid] for pid in plist) <= vessels[v]["fatigue"], name=f"fat_{v}_{d}")

# 7. work-hour capacity with co-visit saving
for p in patterns:
    wos = [w for w in work_orders if (w["id"], p["id"]) in eligible]
    if not wos:
        continue
    hours_expr = quicksum(w["hours"] * y[(w["id"], p["id"])] for w in wos)
    saving_expr = quicksum(CO_VISIT * sv[(p["id"], t)] for t in p["turbines"] if (p["id"], t) in sv)
    model.addCons(hours_expr - saving_expr <= p["cap"], name=f"hours_{p['id']}")
    # sv <= n_t - 1  (i.e., sv + (1 - n_t) <= 0 -> n_t - sv >= 1 when sv=1)
    for t in p["turbines"]:
        if (p["id"], t) in sv:
            n_t = quicksum(y[(w["id"], p["id"])] for w in work_orders if w["turbine"] == t and (w["id"], p["id"]) in eligible)
            model.addCons(n_t - sv[(p["id"], t)] >= 1, name=f"svlink_{p['id']}_{t}")

# 8. technician berths
for p in patterns:
    wos = [w for w in work_orders if (w["id"], p["id"]) in eligible]
    if wos:
        model.addCons(quicksum(w["tech"] * y[(w["id"], p["id"])] for w in wos) <= vessels[p["vessel"]]["berths"], name=f"berth_{p['id']}")

# 9. deck spares
for p in patterns:
    wos = [w for w in work_orders if (w["id"], p["id"]) in eligible and w["spare_units"] > 0]
    if wos:
        model.addCons(quicksum(w["spare_units"] * y[(w["id"], p["id"])] for w in wos) <= vessels[p["vessel"]]["deck"], name=f"deck_{p['id']}")

# 10. technician pool
for d in DAYS:
    for s in ["blade", "electrical", "mechanical", "cable"]:
        if (d, s) not in tech_pool:
            continue
        use = quicksum(w["tech"] * w["hours"] * y[(w["id"], p["id"])]
                       for w in work_orders if w["skill"] == s
                       for p in patterns if p["day"] == d and (w["id"], p["id"]) in eligible)
        tp = tech_pool[(d, s)]
        model.addCons(use <= tp["regular"] + ot[(d, s)], name=f"tech_{d}_{s}")

# 11. spare inventory
for d in DAYS:
    for (dd, st), avail in spare_inv.items():
        if dd != d:
            continue
        use = quicksum(w["spare_units"] * y[(w["id"], p["id"])]
                       for w in work_orders if w["spare_type"] == st and w["spare_units"] > 0
                       for p in patterns if p["day"] == d and (w["id"], p["id"]) in eligible)
        model.addCons(use <= avail, name=f"spare_{d}_{st}")

# 12. string daily limits
for d in DAYS:
    for sname, (maxm, maxt) in string_limits.items():
        mand_use = quicksum(y[(w["id"], p["id"])]
                            for w in work_orders if w["mandatory"] and turbines.get(w["turbine"]) == sname
                            for p in patterns if p["day"] == d and (w["id"], p["id"]) in eligible)
        tot_use = quicksum(y[(w["id"], p["id"])]
                           for w in work_orders if turbines.get(w["turbine"]) == sname
                           for p in patterns if p["day"] == d and (w["id"], p["id"]) in eligible)
        model.addCons(mand_use <= maxm, name=f"strmand_{sname}_{d}")
        model.addCons(tot_use <= maxt, name=f"strtot_{sname}_{d}")

# completion day definition
for w in work_orders:
    model.addCons(dayv[w["id"]] == quicksum(p["day"] * y[(w["id"], p["id"])] for p in patterns if (w["id"], p["id"]) in eligible), name=f"daydef_{w['id']}")

# lateness definition
for w in work_orders:
    for p in patterns:
        if (w["id"], p["id"]) in eligible:
            model.addCons(latv[w["id"]] >= p["day"] - w["due"] - (w["latest"] - w["due"]) * (1 - y[(w["id"], p["id"])]), name=f"lat_{w['id']}_{p['id']}")

# same-turbine credit linking
for (wid, pid), cv in cvar.items():
    w = wo_by_id[wid]
    p = pat_by_id[pid]
    mand_at_t = [w2 for w2 in work_orders if w2["mandatory"] and w2["turbine"] == w["turbine"] and (w2["id"], pid) in eligible]
    cv_ub = quicksum(y[(w2["id"], pid)] for w2 in mand_at_t)
    model.addCons(cv <= y[(wid, pid)], name=f"clink1_{wid}_{pid}")
    model.addCons(cv <= cv_ub, name=f"clink2_{wid}_{pid}")

# string credit linking
for rule in string_rules:
    for d in DAYS:
        # u <= y
        for (rid, wid, pid), uv in uvar.items():
            if rid != rule["id"]:
                continue
            p = pat_by_id[pid]
            if p["day"] != d:
                continue
            model.addCons(uv <= y[(wid, pid)], name=f"ulink1_{rid}_{wid}_{pid}")
        # u <= anchor completed on day d
        anchor_on_d = quicksum(y[(rule["anchor"], p2["id"])] for p2 in patterns if p2["day"] == d and (rule["anchor"], p2["id"]) in eligible)
        for (rid, wid, pid), uv in uvar.items():
            if rid != rule["id"]:
                continue
            p = pat_by_id[pid]
            if p["day"] != d:
                continue
            model.addCons(uv <= anchor_on_d, name=f"ulink2_{rid}_{wid}_{pid}")
        # per-day cap
        day_uses = [uv for (rid, wid, pid), uv in uvar.items() if rid == rule["id"] and pat_by_id[pid]["day"] == d]
        if day_uses:
            model.addCons(quicksum(day_uses) <= rule["max"], name=f"ucap_{rid}_{d}")

# ---------------- Objective ----------------
obj_terms = []

# route costs
for p in patterns:
    obj_terms.append(p["cost"] * x[p["id"]])

# lateness
for w in work_orders:
    if w["lateness"] > 0:
        obj_terms.append(w["lateness"] * latv[w["id"]])

# downtime: from earliest day through completion day -> (day - earliest + 1) days
for w in work_orders:
    if w["mandatory"] and w["downtime"] > 0:
        obj_terms.append(w["downtime"] * (dayv[w["id"]] - w["earliest"] + 1))

# deferral
for w in work_orders:
    if (not w["mandatory"]) and w["deferral"] > 0:
        obj_terms.append(w["deferral"] * (1 - z[w["id"]]))

# overtime cost
for (d, s), ov in ot.items():
    obj_terms.append(tech_pool[(d, s)]["ot_cost"] * ov)

# same-turbine credits (negative)
for (wid, pid), cv in cvar.items():
    obj_terms.append(-wo_by_id[wid]["credit"] * cv)

# string credits (negative)
for (rid, wid, pid), uv in uvar.items():
    rule = [r for r in string_rules if r["id"] == rid][0]
    obj_terms.append(-rule["credit"] * uv)

obj_expr = quicksum(obj_terms)
model.setObjective(obj_expr, sense="minimize")

# ---------------- Solve ----------------
try:
    model.optimize()
    status = model.getStatus()
    nbest = model.getNSols()
    if nbest > 0:
        sol = model.getBestSol()
        objval = model.getObjVal()
    else:
        objval = None
    print(f"status={status} objective={objval} nsols={nbest} time={model.getSolTime(model.getBestSol()) if nbest>0 else 0}")
except Exception as e:
    print(f"solver error: {e}")
    status = "error"
    objval = None

# ---------------- Extract solution ----------------
route_rows = []
work_rows = []
errors = []

def val(var):
    try:
        return model.getVal(var)
    except Exception:
        return 0.0

if status in ("optimal", "gap", "timelimit", "bestsolsfound"):
    for p in patterns:
        if val(x[p["id"]]) > 0.5:
            route_rows.append(("route", p["day"], p["vessel"], p["id"], ""))
    for w in work_orders:
        for p in patterns:
            if (w["id"], p["id"]) in eligible and val(y[(w["id"], p["id"])]) > 0.5:
                work_rows.append(("work", p["day"], p["vessel"], p["id"], w["id"]))

# ---------------- Validation ----------------
# mandatory completion
done = {}
for (rt, d, v, pid, tid) in work_rows:
    if tid:
        done.setdefault(tid, []).append((d, v, pid))
for w in work_orders:
    if w["mandatory"]:
        if w["id"] not in done:
            errors.append(f"mandatory {w['id']} not scheduled")
        else:
            if len(done[w["id"]]) != 1:
                errors.append(f"mandatory {w['id']} scheduled {len(done[w['id']])} times")
            else:
                d, v, pid = done[w["id"]][0]
                if not (w["earliest"] <= d <= w["latest"]):
                    errors.append(f"{w['id']} day {d} outside window")

# one pattern per vessel per day
seen = {}
for (rt, d, v, pid, tid) in route_rows:
    key = (d, v)
    if key in seen:
        errors.append(f"vessel {v} day {d} has two patterns {seen[key]},{pid}")
    seen[key] = pid

# work-hour capacity with co-visit saving
for p in patterns:
    wos = [w for w in work_orders if (w["id"], p["id"]) in eligible]
    if not wos:
        continue
    total_h = 0.0
    per_t = {}
    for w in wos:
        if (w["id"], p["id"]) in eligible and val(y[(w["id"], p["id"])]) > 0.5:
            total_h += w["hours"]
            per_t[w["turbine"]] = per_t.get(w["turbine"], 0) + 1
    saving = sum(CO_VISIT * max(0, n - 1) for n in per_t.values())
    if total_h - saving > p["cap"] + 1e-6:
        errors.append(f"{p['id']} hours {total_h - saving:.4f} > cap {p['cap']}")

# turnaround
for prev, nxt in turnaround:
    if val(x.get(prev, 0)) > 0.5 and val(x.get(nxt, 0)) > 0.5:
        errors.append(f"turnaround violation {prev}->{nxt}")

# fatigue
for v in vessels:
    for d in DAYS:
        fsum = sum(pat_by_id[pid]["fatigue"] * val(x[pid]) for pid in x if pat_by_id[pid]["vessel"] == v and pat_by_id[pid]["day"] in (d, d + 1))
        if fsum > vessels[v]["fatigue"] + 1e-6:
            errors.append(f"fatigue {v} day {d}: {fsum} > {vessels[v]['fatigue']}")

# sailing limits
for v in vessels:
    ns = sum(1 for pid in x if pat_by_id[pid]["vessel"] == v and val(x[pid]) > 0.5)
    if ns > sail_limits.get(v, 99):
        errors.append(f"sailing limit {v}: {ns}")

# technician pool
for d in DAYS:
    for s in ["blade", "electrical", "mechanical", "cable"]:
        if (d, s) not in tech_pool:
            continue
        use = sum(w["tech"] * w["hours"] for w in work_orders if w["skill"] == s for p in patterns if p["day"] == d and (w["id"], p["id"]) in eligible and val(y[(w["id"], p["id"])]) > 0.5)
        if use > tech_pool[(d, s)]["regular"] + tech_pool[(d, s)]["ot_hours"] + 1e-6:
            errors.append(f"tech pool {d} {s}: {use} > {tech_pool[(d,s)]['regular']+tech_pool[(d,s)]['ot_hours']}")

# spare inventory
for d in DAYS:
    for (dd, st), avail in spare_inv.items():
        if dd != d:
            continue
        use = sum(w["spare_units"] for w in work_orders if w["spare_type"] == st and w["spare_units"] > 0 for p in patterns if p["day"] == d and (w["id"], p["id"]) in eligible and val(y[(w["id"], p["id"])]) > 0.5)
        if use > avail + 1e-6:
            errors.append(f"spare {d} {st}: {use} > {avail}")

# string daily limits
for d in DAYS:
    for sname, (maxm, maxt) in string_limits.items():
        mand = sum(1 for w in work_orders if w["mandatory"] and turbines.get(w["turbine"]) == sname for p in patterns if p["day"] == d and (w["id"], p["id"]) in eligible and val(y[(w["id"], p["id"])]) > 0.5)
        tot = sum(1 for w in work_orders if turbines.get(w["turbine"]) == sname for p in patterns if p["day"] == d and (w["id"], p["id"]) in eligible and val(y[(w["id"], p["id"])]) > 0.5)
        if mand > maxm:
            errors.append(f"string {sname} day {d} mandatory {mand} > {maxm}")
        if tot > maxt:
            errors.append(f"string {sname} day {d} total {tot} > {maxt}")

print("validation errors:", errors if errors else "none")

# ---------------- Write solution ----------------
sol_path = os.path.join(OUT, "solution.csv")
with open(sol_path, "w", newline="") as f:
    wtr = csv.writer(f)
    wtr.writerow(["record_type", "day", "vessel_id", "pattern_id", "task_id"])
    for row in sorted(route_rows, key=lambda r: (r[1], r[2], r[3])):
        wtr.writerow(row)
    for row in sorted(work_rows, key=lambda r: (r[1], r[2], r[4])):
        wtr.writerow(row)
print(f"wrote {sol_path} with {len(route_rows)+len(work_rows)} rows")

model.free()
